<script setup>
import {computed,ref} from 'vue'
const props=defineProps({data:Object,themed:Boolean})
const values=ref({})
const nodes=computed(()=>{const items=[];function visit(n){if(n.type!=='Page'&&n.bounds.y>=40)items.push(n);for(const c of n.children||[])visit(c)}visit(props.data.root);return items.sort((a,b)=>a.paintIndex-b.paintIndex)})
function style(n){const s=n.styles||{},b=n.bounds,transparent=c=>!c||c==='#00000000'||c==='transparent';let bg=s.backgroundColor,color=s.color;const borders=s.borderWidth||{};if(props.themed){if(!transparent(bg))bg=['#ffffff','#fff'].includes(bg)?'#ffffff':['#1f2937','#111827'].includes(bg)?'#f9c54d':'#f8eed3';if(!transparent(color))color='#131414';if(n.type==='Button'){bg='#f9c54d';color='#131414'}}return {left:b.x+'px',top:(b.y-40)+'px',width:b.width+'px',height:b.height+'px',backgroundColor:bg,color:transparent(color)?undefined:color,fontSize:(s.fontSize||14)+'px',fontWeight:s.fontWeight||400,fontFamily:props.themed?'IBM Plex Sans, sans-serif':(s.fontFamily||'sans-serif'),textAlign:s.textAlign||'left',opacity:s.opacity??1,borderColor:props.themed?'#13141433':s.borderColor,borderStyle:'solid',borderWidth:['top','right','bottom','left'].map(k=>(borders[k]||0)+'px').join(' '),borderRadius:props.themed?(n.type==='Button'?'999px':n.type==='Card'?'16px':n.type==='Input'?'8px':'0'):(s.borderRadius?.topLeft||0)+'px',zIndex:n.paintIndex}}
function isText(n){return ['Text','Heading','Button','Badge','Chip'].includes(n.type)}
</script>
<template><div class="wireframe-canvas" :style="{width:data.canvas.width+'px',height:(data.canvas.height-40)+'px',background:themed?'#faf7f0':data.canvas.backgroundColor}"><template v-for="n in nodes" :key="n.id"><img v-if="n.type==='Image'&&n.properties.src?.startsWith('data:')" :src="n.properties.src" :style="style(n)" class="wf-node" alt=""><div v-else-if="n.type==='Image'" :style="style(n)" class="wf-node wf-placeholder" aria-label="Vùng hình ảnh trong wireframe"><svg viewBox="0 0 100 100" preserveAspectRatio="none"><path d="M0 0L100 100M100 0L0 100" fill="none" stroke="currentColor" stroke-width=".5"/></svg></div><input v-else-if="n.type==='Input'" :style="style(n)" class="wf-node" v-model="values[n.id]" :placeholder="n.properties.placeholder||n.properties.text" :aria-label="n.properties.placeholder||n.properties.text||'Ô nhập trong wireframe'"><textarea v-else-if="n.type==='Textarea'" :style="style(n)" class="wf-node" v-model="values[n.id]" :aria-label="n.properties.text||'Nội dung trong wireframe'"></textarea><label v-else-if="['Checkbox','Radio'].includes(n.type)" :style="style(n)" class="wf-node wf-check"><input :type="n.type==='Checkbox'?'checkbox':'radio'" :name="'wf-'+(Math.round(n.bounds.y/150))" :checked="n.properties.checked">{{n.properties.text}}</label><select v-else-if="n.type==='Select'" :style="style(n)" class="wf-node" :aria-label="n.properties.text||'Lựa chọn'"><option>{{n.properties.text||'Chọn'}}</option></select><component v-else :is="n.type==='Button'?'button':'div'" :style="style(n)" class="wf-node" :class="{'wf-text':isText(n)}" :title="n.properties.text"><template v-if="isText(n)">{{n.properties.text}}</template></component></template></div></template>
